  async function addFiscalNcm(dados) {
    if (!canAccess(currentUser, "admin")) return notify("error", "Sem permissão administrativa.");
    if (!dados?.codigo?.trim()) return notify("error", "Informe o código do NCM.");
    // Evita duplicidade: mesmo código (comparando só os dígitos) já cadastrado.
    if (fiscalNcm.some((n) => soDigitos(n.codigo) === soDigitos(dados.codigo))) return notify("error", `NCM ${dados.codigo} já está cadastrado.`);
    const p = { ...dados, codigo: dados.codigo.trim(), lojaId: lojaAtual };
    try {
      const saved = dbReady ? await inserirFiscalNcm(p) : { ...p, id: Date.now(), ativo: true };
      setFiscalNcm((cur) => [...cur, saved].sort((a, b) => String(a.codigo).localeCompare(String(b.codigo))));
    } catch (e) { notify("error", "Erro ao salvar NCM: " + (e.message || e)); return; }
    auditar("criar", "fiscal_ncm", null, { codigo: p.codigo });
    notify("success", "NCM cadastrado.");
    return true;
  }
  async function editarFiscalNcm(id, dados) {
    if (!canAccess(currentUser, "admin")) return notify("error", "Sem permissão administrativa.");
    setFiscalNcm((cur) => cur.map((p) => p.id === id ? { ...p, ...dados } : p));
    if (dbReady) try { await atualizarFiscalNcm(id, dados); } catch (e) { notify("error", "Erro ao salvar NCM: " + (e.message || e)); }
    auditar("editar", "fiscal_ncm", id, { codigo: dados?.codigo });
    return true;
  }
  async function removerFiscalNcm(id) {
    if (!canAccess(currentUser, "admin")) return notify("error", "Sem permissão administrativa.");
    setFiscalNcm((cur) => cur.filter((p) => p.id !== id));
    if (dbReady) try { await excluirFiscalNcm(id); } catch (e) { notify("error", "Erro ao excluir NCM: " + (e.message || e)); }
    auditar("excluir", "fiscal_ncm", id);
  }
  // NCM em lote (perf): exclusão / ativar-inativar de vários ids de uma vez.
  async function excluirFiscalNcmEmLote(ids) {
    if (!canAccess(currentUser, "admin")) return notify("error", "Sem permissão administrativa.");
    if (!ids?.length) return;
    const set = new Set(ids.map(String));
    setFiscalNcm((cur) => cur.filter((n) => !set.has(String(n.id))));
    if (dbReady) try { await excluirFiscalNcmLote(ids); } catch (e) { notify("error", "Erro ao excluir NCMs: " + (e.message || e)); }
    auditar("excluir_lote", "fiscal_ncm", null, { qtd: ids.length });
    notify("success", `${ids.length} NCM(s) excluído(s).`);
  }
  async function inativarFiscalNcmEmLote(ids, ativo) {
    if (!canAccess(currentUser, "admin")) return notify("error", "Sem permissão administrativa.");
    if (!ids?.length) return;
    const set = new Set(ids.map(String));
    setFiscalNcm((cur) => cur.map((n) => set.has(String(n.id)) ? { ...n, ativo: !!ativo } : n));
    if (dbReady) try { await atualizarFiscalNcmLoteAtivo(ids, ativo); } catch (e) { notify("error", "Erro ao atualizar NCMs: " + (e.message || e)); }
    auditar(ativo ? "ativar_lote" : "inativar_lote", "fiscal_ncm", null, { qtd: ids.length });
  }
  // Importação da TIPI (XLSX): insere NCMs válidos em blocos, reportando o
  // progresso via callback. `linhas` já vem validada e sem duplicatas.
  async function importarFiscalNcmLote(linhas, onProgress) {
    if (!canAccess(currentUser, "admin")) { notify("error", "Sem permissão administrativa."); return 0; }
    const CHUNK = 200;
    let inseridos = [];
    for (let i = 0; i < linhas.length; i += CHUNK) {
      const parte = linhas.slice(i, i + CHUNK).map((l) => ({ ...l, lojaId: lojaAtual, ativo: true }));
      try {
        const saved = dbReady ? await inserirFiscalNcmLote(parte) : parte.map((l) => ({ ...l, id: gerarIdLocal() }));
        inseridos = inseridos.concat(saved);
      } catch (e) { notify("error", "Erro na importação: " + (e.message || e)); break; }
      onProgress?.(Math.min(i + CHUNK, linhas.length), linhas.length);
    }
    if (inseridos.length) {
      setFiscalNcm((cur) => [...cur, ...inseridos].sort((a, b) => String(a.codigo).localeCompare(String(b.codigo))));
      auditar("importar", "fiscal_ncm", null, { qtd: inseridos.length });
      notify("success", `${inseridos.length} NCM(s) importado(s) da TIPI.`);
    }
    return inseridos.length;
  }
  // Atualização fiscal em lote (Fase 3): aplica os vínculos escolhidos aos
  // produtos informados (objetos), registra cada alteração (valor anterior →
  // posterior, data, usuário) no histórico e na auditoria, permitindo reverter.
  const MAPA_FISCAL_COL = { ncmId: "ncm_id", cfopId: "cfop_id", pisId: "pis_id", cofinsId: "cofins_id", ipiId: "ipi_id", cestId: "cest_id" };
  async function aplicarFiscalLote(afetados, alteracoes) {
    if (!canAccess(currentUser, "admin")) return notify("error", "Sem permissão administrativa.");
    if (!afetados?.length || !Object.keys(alteracoes || {}).length) return notify("error", "Selecione produtos e ao menos uma alteração.");
    const chaves = Object.keys(alteracoes);
    const patch = {};
    for (const k of chaves) patch[MAPA_FISCAL_COL[k]] = alteracoes[k] != null ? alteracoes[k] : null;
    const ids = afetados.map((p) => p.id);
    const loteId = `L${Date.now().toString(36)}-${gerarTid()}`;
    // Registros de histórico: só os campos que realmente mudam em cada produto.
    const registros = [];
    for (const p of afetados) for (const k of chaves) {
      if (String(p[k] ?? "") !== String(alteracoes[k] ?? "")) {
        registros.push({ lojaId: lojaAtual, loteId, produtoId: p.id, produtoNome: p.name, campo: k, valorAnterior: p[k] ?? null, valorPosterior: alteracoes[k] ?? null, usuarioId: currentUser?.id ?? null, usuarioNome: currentUser?.name || currentUser?.email || "—" });
      }
    }
    const idSet = new Set(ids.map(String));
    setProducts((cur) => cur.map((p) => idSet.has(String(p.id)) ? { ...p, ...alteracoes } : p));
    if (dbReady) {
      try { await atualizarProdutosFiscalLote(ids, patch); } catch (e) { notify("error", "Erro na atualização em lote: " + (e.message || e)); return; }
      try { const salvos = await inserirFiscalLoteLog(registros); setFiscalLoteLog((cur) => [...salvos, ...cur]); } catch { /* migration 084 pendente — segue sem histórico */ }
    }
    auditar("editar_lote", "produto", null, { loteId, qtd: ids.length, campos: chaves, alteracoes: registros.length });
    notify("success", `Atualização aplicada a ${ids.length} produto(s).`);
    return true;
  }
  // Fase 5 — vincula produtos à configuração fiscal da loja (individual ou lote).
  // configId null = desvincula. Mantém os campos fiscais atuais intactos.
  async function vincularProdutosConfigFiscal(ids, configId) {
    if (!canAccess(currentUser, "admin")) return notify("error", "Sem permissão administrativa.");
    if (!ids?.length) return notify("error", "Selecione ao menos um produto.");
    const idSet = new Set(ids.map(String));
    setProducts((cur) => cur.map((p) => idSet.has(String(p.id)) ? { ...p, lojaFiscalRegraId: configId ?? null } : p));
    if (dbReady) try { await atualizarProdutosFiscalLote(ids, { loja_fiscal_regra_id: configId ?? null }); } catch (e) { notify("error", "Erro ao vincular: " + (e.message || e)); return; }
    auditar("vincular_fiscal", "produto", null, { qtd: ids.length, configId: configId ?? null });
    notify("success", configId ? `${ids.length} produto(s) vinculado(s) à configuração fiscal.` : `${ids.length} produto(s) desvinculado(s).`);
    return true;
  }
  // Reverter: devolve os campos ao valor anterior registrado. `logs` = linhas do
  // histórico (de um lote inteiro ou uma só). Marca como revertido.
  async function reverterFiscalLote(logs) {
    if (!canAccess(currentUser, "admin")) return notify("error", "Sem permissão administrativa.");
    const alvo = (logs || []).filter((l) => !l.revertido);
    if (!alvo.length) return;
    // Agrupa por produto para montar 1 patch por produto (com os valores anteriores).
    const porProduto = new Map();
    for (const l of alvo) { const m = porProduto.get(l.produtoId) || {}; m[l.campo] = l.valorAnterior ?? null; porProduto.set(l.produtoId, m); }
    for (const [pid, campos] of porProduto) {
      const patch = {}; for (const k of Object.keys(campos)) patch[MAPA_FISCAL_COL[k]] = campos[k];
      setProducts((cur) => cur.map((p) => String(p.id) === String(pid) ? { ...p, ...campos } : p));
      if (dbReady) try { await atualizarProdutosFiscalLote([pid], patch); } catch (e) { notify("error", "Erro ao reverter: " + (e.message || e)); return; }
    }
    const ids = alvo.map((l) => l.id);
    setFiscalLoteLog((cur) => cur.map((l) => ids.includes(l.id) ? { ...l, revertido: true, revertidoEm: new Date().toISOString() } : l));
    if (dbReady) try { await marcarFiscalLoteLogRevertido(ids); } catch { /* segue */ }
    auditar("reverter_lote", "produto", null, { qtd: porProduto.size, alteracoes: alvo.length });
    notify("success", `${alvo.length} alteração(ões) revertida(s).`);
    return true;
  }

  // Handlers CRUD dos cadastros fiscais simples (CFOP, PIS, COFINS, IPI, CEST).
  // Declarações hoisted (referência estável) que delegam aos genéricos de
  // módulo — `ctx`/`cfg` são montados só na invocação (evento), não no render.
  const ctxFiscal = () => ({ podeAdmin: canAccess(currentUser, "admin"), notify, auditar, dbReady, lojaAtual });
  const CFG_CFOP = { entidade: "fiscal_cfop", rotulo: "CFOP", campoObrig: "codigo", ordenarPor: "codigo", setState: setFiscalCfop, inserirFn: inserirFiscalCfop, atualizarFn: atualizarFiscalCfop, excluirFn: excluirFiscalCfop };
  const CFG_PIS = { entidade: "fiscal_pis", rotulo: "PIS", campoObrig: "descricao", ordenarPor: "descricao", setState: setFiscalPis, inserirFn: inserirFiscalPis, atualizarFn: atualizarFiscalPis, excluirFn: excluirFiscalPis };
  const CFG_COFINS = { entidade: "fiscal_cofins", rotulo: "COFINS", campoObrig: "descricao", ordenarPor: "descricao", setState: setFiscalCofins, inserirFn: inserirFiscalCofins, atualizarFn: atualizarFiscalCofins, excluirFn: excluirFiscalCofins };
  const CFG_IPI = { entidade: "fiscal_ipi", rotulo: "IPI", campoObrig: "descricao", ordenarPor: "descricao", setState: setFiscalIpi, inserirFn: inserirFiscalIpi, atualizarFn: atualizarFiscalIpi, excluirFn: excluirFiscalIpi };
  const CFG_CEST = { entidade: "fiscal_cest", rotulo: "CEST", campoObrig: "codigo", ordenarPor: "codigo", setState: setFiscalCest, inserirFn: inserirFiscalCest, atualizarFn: atualizarFiscalCest, excluirFn: excluirFiscalCest };
  const hCfop = { add: (d) => fiscalCrudAdd(ctxFiscal(), CFG_CFOP, d), editar: (id, d) => fiscalCrudEditar(ctxFiscal(), CFG_CFOP, id, d), remover: (id) => fiscalCrudRemover(ctxFiscal(), CFG_CFOP, id) };
  const hPis = { add: (d) => fiscalCrudAdd(ctxFiscal(), CFG_PIS, d), editar: (id, d) => fiscalCrudEditar(ctxFiscal(), CFG_PIS, id, d), remover: (id) => fiscalCrudRemover(ctxFiscal(), CFG_PIS, id) };
  const hCofins = { add: (d) => fiscalCrudAdd(ctxFiscal(), CFG_COFINS, d), editar: (id, d) => fiscalCrudEditar(ctxFiscal(), CFG_COFINS, id, d), remover: (id) => fiscalCrudRemover(ctxFiscal(), CFG_COFINS, id) };
  const hIpi = { add: (d) => fiscalCrudAdd(ctxFiscal(), CFG_IPI, d), editar: (id, d) => fiscalCrudEditar(ctxFiscal(), CFG_IPI, id, d), remover: (id) => fiscalCrudRemover(ctxFiscal(), CFG_IPI, id) };
  const hCest = { add: (d) => fiscalCrudAdd(ctxFiscal(), CFG_CEST, d), editar: (id, d) => fiscalCrudEditar(ctxFiscal(), CFG_CEST, id, d), remover: (id) => fiscalCrudRemover(ctxFiscal(), CFG_CEST, id) };

  // ── Central Fiscal Prime — catálogos globais (migration 085, super admin) ──
  // Segue o padrão dos handlers fiscais: CFG em constante + objeto literal com
  // arrows que chamam os genéricos de escopo de módulo (sem função no render).
  const ctxCatalogo = () => ({ ehSuper: !!currentUser?.superAdmin, usuarioId: currentUser?.id ?? null, notify, auditar, dbReady });
  const CAT_NCM = { entidade: "cat_ncm", rotulo: "NCM", setState: setCatNcm, inserirFn: inserirCatNcm, atualizarFn: atualizarCatNcm, excluirFn: excluirCatNcm };
  const CAT_CEST = { entidade: "cat_cest", rotulo: "CEST", setState: setCatCest, inserirFn: inserirCatCest, atualizarFn: atualizarCatCest, excluirFn: excluirCatCest };
  const CAT_CFOP = { entidade: "cat_cfop", rotulo: "CFOP", setState: setCatCfop, inserirFn: inserirCatCfop, atualizarFn: atualizarCatCfop, excluirFn: excluirCatCfop };
  const CAT_CST_ICMS = { entidade: "cat_cst_icms", rotulo: "CST ICMS", setState: setCatCstIcms, inserirFn: inserirCatCstIcms, atualizarFn: atualizarCatCstIcms, excluirFn: excluirCatCstIcms };
  const CAT_CSOSN = { entidade: "cat_csosn", rotulo: "CSOSN", setState: setCatCsosn, inserirFn: inserirCatCsosn, atualizarFn: atualizarCatCsosn, excluirFn: excluirCatCsosn };
  const CAT_CST_PIS = { entidade: "cat_cst_pis", rotulo: "CST PIS", setState: setCatCstPis, inserirFn: inserirCatCstPis, atualizarFn: atualizarCatCstPis, excluirFn: excluirCatCstPis };
  const CAT_CST_COFINS = { entidade: "cat_cst_cofins", rotulo: "CST COFINS", setState: setCatCstCofins, inserirFn: inserirCatCstCofins, atualizarFn: atualizarCatCstCofins, excluirFn: excluirCatCstCofins };
  const centralFiscalApi = {
    ncm: { add: (d) => catalogoCrudAdd(ctxCatalogo(), CAT_NCM, d), editar: (id, d) => catalogoCrudEditar(ctxCatalogo(), CAT_NCM, id, d), remover: (id) => catalogoCrudRemover(ctxCatalogo(), CAT_NCM, id) },
    cest: { add: (d) => catalogoCrudAdd(ctxCatalogo(), CAT_CEST, d), editar: (id, d) => catalogoCrudEditar(ctxCatalogo(), CAT_CEST, id, d), remover: (id) => catalogoCrudRemover(ctxCatalogo(), CAT_CEST, id) },
    cfop: { add: (d) => catalogoCrudAdd(ctxCatalogo(), CAT_CFOP, d), editar: (id, d) => catalogoCrudEditar(ctxCatalogo(), CAT_CFOP, id, d), remover: (id) => catalogoCrudRemover(ctxCatalogo(), CAT_CFOP, id) },
    cstIcms: { add: (d) => catalogoCrudAdd(ctxCatalogo(), CAT_CST_ICMS, d), editar: (id, d) => catalogoCrudEditar(ctxCatalogo(), CAT_CST_ICMS, id, d), remover: (id) => catalogoCrudRemover(ctxCatalogo(), CAT_CST_ICMS, id) },
    csosn: { add: (d) => catalogoCrudAdd(ctxCatalogo(), CAT_CSOSN, d), editar: (id, d) => catalogoCrudEditar(ctxCatalogo(), CAT_CSOSN, id, d), remover: (id) => catalogoCrudRemover(ctxCatalogo(), CAT_CSOSN, id) },
    cstPis: { add: (d) => catalogoCrudAdd(ctxCatalogo(), CAT_CST_PIS, d), editar: (id, d) => catalogoCrudEditar(ctxCatalogo(), CAT_CST_PIS, id, d), remover: (id) => catalogoCrudRemover(ctxCatalogo(), CAT_CST_PIS, id) },
    cstCofins: { add: (d) => catalogoCrudAdd(ctxCatalogo(), CAT_CST_COFINS, d), editar: (id, d) => catalogoCrudEditar(ctxCatalogo(), CAT_CST_COFINS, id, d), remover: (id) => catalogoCrudRemover(ctxCatalogo(), CAT_CST_COFINS, id) },
  };

  // ── Regras Fiscais + versionamento (migration 086, super admin) ──
  // Após cada operação recarrega regras+versões (conjuntos pequenos, globais).
  const recarregarRegras = async () => {
    try { setFiscalRegras(await fetchFiscalRegras()); } catch { /* migration 086 pendente */ }
    try { setFiscalRegraVersoes(await fetchFiscalRegraVersoes()); } catch { /* migration 086 pendente */ }
  };
  async function addRegraFiscal(regra, versao) {
    if (!isSuperAdmin) return notify("error", "Apenas o super administrador pode criar regras fiscais.");
    if (!String(regra?.nome || "").trim()) return notify("error", "Informe o nome da regra fiscal.");
    if (!dbReady) return notify("error", "Banco indisponível. Aplique a migration 086.");
    try { await inserirFiscalRegra({ ...regra, criadoPor: currentUser?.id ?? null }, versao || {}); }
    catch (e) { return notify("error", "Erro ao criar regra: " + (e.message || e)); }
    await recarregarRegras(); auditar("criar", "fiscal_regra", null, { nome: regra.nome });
    notify("success", "Regra fiscal criada (rascunho da versão 1)."); return true;
  }
  async function editarRegraHeader(id, campos) {
    if (!isSuperAdmin) return notify("error", "Sem permissão.");
    if (dbReady) try { await atualizarFiscalRegra(id, { ...campos, atualizadoPor: currentUser?.id ?? null }); } catch (e) { return notify("error", "Erro ao salvar regra: " + (e.message || e)); }
    await recarregarRegras(); auditar("editar", "fiscal_regra", id); return true;
  }
  async function salvarVersaoRascunho(id, campos) {
    if (!isSuperAdmin) return notify("error", "Sem permissão.");
    if (dbReady) try { await atualizarFiscalRegraVersao(id, campos); } catch (e) { return notify("error", "Erro ao salvar versão: " + (e.message || e)); }
    await recarregarRegras(); auditar("editar", "fiscal_regra_versao", id); return true;
  }
  async function publicarVersaoRegra({ regraId, versaoId, versao }) {
    if (!isSuperAdmin) return notify("error", "Sem permissão.");
    if (dbReady) try { await publicarFiscalRegraVersao({ regraId, versaoId, versao, usuarioId: currentUser?.id ?? null }); } catch (e) { return notify("error", "Erro ao publicar: " + (e.message || e)); }
    await recarregarRegras(); auditar("publicar", "fiscal_regra_versao", versaoId, { versao });
    notify("success", `Versão ${versao} publicada.`); return true;
  }
  async function criarNovaVersaoRegra(regraId, base) {
    if (!isSuperAdmin) return notify("error", "Sem permissão.");
    if (dbReady) try { await novaVersaoFiscalRegra({ regraId, base, usuarioId: currentUser?.id ?? null }); } catch (e) { return notify("error", "Erro ao criar versão: " + (e.message || e)); }
    await recarregarRegras(); auditar("criar", "fiscal_regra_versao", regraId);
    notify("success", "Nova versão criada em rascunho."); return true;
  }
  async function inativarRegraFiscal(regraId, inativa) {
    if (!isSuperAdmin) return notify("error", "Sem permissão.");
    if (dbReady) try { await inativarFiscalRegra(regraId, inativa); } catch (e) { return notify("error", "Erro: " + (e.message || e)); }
    await recarregarRegras(); auditar(inativa ? "inativar" : "reativar", "fiscal_regra", regraId); return true;
  }
  async function removerRegraFiscal(regraId) {
    if (!isSuperAdmin) return notify("error", "Sem permissão.");
    if (dbReady) try { await excluirFiscalRegra(regraId); } catch (e) { return notify("error", "Erro ao excluir: " + (e.message || e)); }
    await recarregarRegras(); auditar("excluir", "fiscal_regra", regraId); return true;
  }
  const regrasFiscalApi = {
    add: addRegraFiscal, editarHeader: editarRegraHeader, salvarVersao: salvarVersaoRascunho,
    publicar: publicarVersaoRegra, novaVersao: criarNovaVersaoRegra, inativar: inativarRegraFiscal, remover: removerRegraFiscal,
  };

  // ── Configuração Fiscal da Loja — importação da Central (migration 087) ──
  const recarregarLojaRegras = async () => { try { setLojaFiscalRegras(await fetchLojaFiscalRegras()); } catch { /* migration 087 pendente */ } };
  async function importarRegraParaLoja({ regraGlobalId, regraNome, versao, snapshot }) {
    if (lojaAtual == null) return notify("error", "Selecione a empresa em foco para importar.");
    if (!dbReady) return notify("error", "Banco indisponível. Aplique a migration 087.");
    try { await importarLojaFiscalRegra({ lojaId: lojaAtual, regraGlobalId, regraNome, versao, snapshot }); }
    catch (e) { return notify("error", "Erro ao importar: " + (e.message || e)); }
    await recarregarLojaRegras(); auditar("importar", "loja_fiscal_regra", regraGlobalId, { regra: regraNome, versao });
    notify("success", `Regra "${regraNome}" importada para a sua loja (v${versao}).`); return true;
  }
  async function salvarLojaRegra(id, campos) {
    if (dbReady) try { await atualizarLojaFiscalRegra(id, campos); } catch (e) { return notify("error", "Erro ao salvar: " + (e.message || e)); }
    await recarregarLojaRegras(); auditar("editar", "loja_fiscal_regra", id); notify("success", "Configuração da loja atualizada."); return true;
  }
  async function aplicarVersaoLojaRegra(id, { versao, snapshot }) {
    if (dbReady) try { await aplicarVersaoLojaFiscalRegra(id, { versao, snapshot }); } catch (e) { return notify("error", "Erro ao atualizar: " + (e.message || e)); }
    await recarregarLojaRegras(); auditar("atualizar", "loja_fiscal_regra", id, { versao }); notify("success", `Configuração atualizada para a versão ${versao}.`); return true;
  }
  async function manterVersaoLojaRegra(id, versao, ignorar = false) {
    if (dbReady) try { await marcarChecadaLojaFiscalRegra(id, versao); } catch (e) { return notify("error", "Erro: " + (e.message || e)); }
    await recarregarLojaRegras(); auditar(ignorar ? "ignorar_atualizacao" : "manter_versao", "loja_fiscal_regra", id, { versao }); return true;
  }
  async function excluirLojaRegra(id) {
    if (dbReady) try { await excluirLojaFiscalRegra(id); } catch (e) { return notify("error", "Erro ao excluir: " + (e.message || e)); }
    await recarregarLojaRegras(); auditar("excluir", "loja_fiscal_regra", id); return true;
  }
  const lojaFiscalApi = { importar: importarRegraParaLoja, salvar: salvarLojaRegra, aplicarVersao: aplicarVersaoLojaRegra, manter: manterVersaoLojaRegra, excluir: excluirLojaRegra, vincularProdutos: vincularProdutosConfigFiscal };

  // ── Templates fiscais por segmento (migration 104, super admin) ──
  const recarregarTemplates = async () => {
    try { setFiscalTemplates(await fetchFiscalTemplates()); } catch { /* migration 104 pendente */ }
    try { setFiscalTemplateRegras(await fetchFiscalTemplateRegras()); } catch { /* migration 104 pendente */ }
  };
  async function addTemplateFiscal(dados) {
    if (!isSuperAdmin) return notify("error", "Apenas o super administrador gerencia templates.");
    if (!String(dados?.nome || "").trim()) return notify("error", "Informe o nome do template.");
    if (!dbReady) return notify("error", "Banco indisponível. Aplique a migration 104.");
    try { await inserirFiscalTemplate({ ...dados, criadoPor: currentUser?.id ?? null }); }
    catch (e) { return notify("error", "Erro ao criar template: " + (e.message || e)); }
    await recarregarTemplates(); auditar("criar", "fiscal_template", null, { nome: dados.nome });
    notify("success", "Template criado."); return true;
  }
